  [446228] = { "Aumenta di $N1 la potenza d'attacco a distanza e in mischia. I benefici di questo tonico valgono solo nelle aree sotto l'influenza dell'Incubo.", "Potenza d'attacco in mischia e a distanza aumentata di $N1.", 0x8e6cd2a6, 0x8ba8f8a1, "uu" },
  [446231] = { "Infonde nell'incantatore una benedizione degli Dei Primordiali. Potenza d'attacco in mischia e a distanza aumentata di $N1 per $D1.", "Potenza d'attacco in mischia aumentata di $N1.\nPotenza d'attacco a distanza aumentata di $N2.", 0x6b1b063b, 0x5b9eb74e, "uu" },
  [446233] = { "Conferisce una piccola probabilità, quando si infliggono danni a distanza o in mischia, di infondere in chi impugna l'arma una benedizione del Serpente. Potenza d'attacco a distanza e in mischia aumentata di $N1 per $D1.", nil, 0x9763b002, nil, "um" },
  [446240] = { "Ottieni un sigillo incantato di Living Dreams, che ti permette di infliggere fino a $N1 danni e cure in più con gli incantesimi e aumenta la potenza d'attacco di $N2 per $D1. Può essere applicato solo fuori dal combattimento.", "Potenziato da Living Dreams. Infliggi fino a $N1 danni e cure in più con gli incantesimi e la tua potenza d'attacco è aumentata di $N2.", 0xc51c03e4, 0xeba25fac, "uu" },
  [446256] = { "Aumenta la potenza magica di $N1. Gli incantesimi andati a segno hanno una probabilità di scagliare un ⟦Shadow Bolt=Dardo d'Ombra⟧ sul bersaglio. Può essere attiva una sola pozione degli Atal'ai alla volta. Non ha effetto fuori dal Tempio di Atal'Hakkar.", "Potenza magica aumentata di $N1. Probabilità, quando un incantesimo va a segno, di lanciare un ⟦Shadow Bolt=Dardo d'Ombra⟧ sul bersaglio.", 0x89a188a5, 0x971b518e, "uu" },
