  [446335] = { "Grazie all'ispirazione del Mojo of War, le tue dimensioni aumentano e la tua Forza aumenta di $N1 per adeguarsi alle nuove dimensioni. Dura $D1.", "Forza aumentata di $N1 e dimensioni aumentate. Senti 'sto voodoo, fratello!", 0xf08ec45b, 0x75b84100, "uu" },
